INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('b14f0e2b-f770-4826-a5b5-d3db23acfa21', '8efcfcca-2753-4215-8e12-a5e3a9466b42', 'uncertainty', 'very_high', 3, 1.3, 'PoC-stage ML models with limited labelled training data introduce fundamental feasibility uncertainty — it is unclear whether accurate 48-72h prediction is achievable, and both the domain and the data pipeline are complex.', '2026-08-05 17:58:53.668313');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('e4b001e6-523e-4c68-a488-abdb141c14e5', '8efcfcca-2753-4215-8e12-a5e3a9466b42', 'reliability_requirement', 'high', 1, 1.1, 'Missed failure predictions or false work orders in a manufacturing environment cause significant financial loss (unplanned downtime, incorrect maintenance dispatch). Not life-safety, but high business impact.', '2026-08-05 17:58:53.668313');
