INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('98a557ad-9258-4b94-9de9-f704e5f01fbf', 'b4ad8da5-369d-4808-9fa6-16ba52adfd5a', 'functional_complexity', 'high', 1, 1.1, 'Randomisation logic, adverse event reporting workflows, query management, and eCTD export are all domain-specific and non-trivial business processes.', '2026-08-05 18:01:47.031776');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('7b5553b8-e273-4420-b0ba-d782380215ce', 'b4ad8da5-369d-4808-9fa6-16ba52adfd5a', 'architectural_complexity', 'medium', 0, 1, 'Multi-tier web application with audit trails, role-based access control, and export pipelines; complex but not distributed microservices.', '2026-08-05 18:01:47.031776');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('bcd8dda1-941b-46be-b823-ad53912efdbf', 'b4ad8da5-369d-4808-9fa6-16ba52adfd5a', 'external_integrations', 'medium', 0, 1, 'FDA eCTD export format and potentially randomisation services; a few complex protocol integrations.', '2026-08-05 18:01:47.031776');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('7e92897f-6021-4000-8e55-87ea4bf07225', 'b4ad8da5-369d-4808-9fa6-16ba52adfd5a', 'requirement_stability', 'very_low', -3, 0.7, '21 CFR Part 11 and FDA eCTD specifications are regulatory requirements that are contractually and legally fixed, leaving virtually no room for scope change.', '2026-08-05 18:01:47.031776');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('709eb1fb-0a82-4d98-8d8c-86bf1eddbd77', 'b4ad8da5-369d-4808-9fa6-16ba52adfd5a', 'uncertainty', 'low', -1, 0.9, 'EDC systems for clinical trials are a well-established domain with known patterns; regulatory requirements are well-documented, though implementation details carry some complexity.', '2026-08-05 18:01:47.031776');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('c89aa0e6-32a7-4f3c-88c4-fd27e7460758', 'b4ad8da5-369d-4808-9fa6-16ba52adfd5a', 'reliability_requirement', 'very_high', 3, 1.3, 'Clinical trial data integrity is safety-critical; errors could endanger patients, invalidate trials, or result in regulatory sanctions.', '2026-08-05 18:01:47.031776');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('1deb5454-744b-408c-ab8d-695290495299', 'b4ad8da5-369d-4808-9fa6-16ba52adfd5a', 'platform_complexity', 'medium', 0, 1, 'Standard multi-tier cloud or on-premise web deployment with audit logging and compliance controls; no embedded or real-time hardware constraints.', '2026-08-05 18:01:47.031776');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('9e24decd-093c-42f1-a2f0-2c313e01360f', 'b4ad8da5-369d-4808-9fa6-16ba52adfd5a', 'schedule_pressure', 'medium', 0, 1, 'No specific deadline mentioned; assuming typical project schedule pressure.', '2026-08-05 18:01:47.031776');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('7bb6290f-3728-460f-86c2-33f15cd9869e', 'b4ad8da5-369d-4808-9fa6-16ba52adfd5a', 'data_complexity', 'high', 1, 1.1, 'Complex clinical data models, audit trails for every change, query management state machines, and structured eCTD export require significant data engineering.', '2026-08-05 18:01:47.031776');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('1f4f500c-1522-4588-af32-06d6a7c75bbd', 'b4ad8da5-369d-4808-9fa6-16ba52adfd5a', 'team_experience_gap', 'high', 1, 1.1, '21 CFR Part 11 compliance, clinical trial domain knowledge, and FDA eCTD formatting require specialised expertise that most development teams lack.', '2026-08-05 18:01:47.031776');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('10e45e8b-a9b3-4ad2-93aa-8f52c34f2d65', 'ef06db4b-b9b1-494b-983d-7c32e6c81b52', 'functional_complexity', 'very_high', 3, 1.3, 'Core bank ledger logic includes complex financial calculations, double-entry accounting, regulatory reporting, and decades of accumulated business rules that must be faithfully reproduced on the new platform.', '2026-08-05 18:02:12.200894');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('a022865c-f8bc-413f-aac8-d470db2d40c9', 'ef06db4b-b9b1-494b-983d-7c32e6c81b52', 'architectural_complexity', 'high', 1, 1.1, 'Zero-downtime cutover and 90-day parallel run require dual-write or event-sourcing patterns, synchronization between AS/400 and Java platforms, and complex cutover orchestration.', '2026-08-05 18:02:12.200894');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('7f96a790-a23f-4363-be63-d94f732ee97f', 'ef06db4b-b9b1-494b-983d-7c32e6c81b52', 'external_integrations', 'very_high', 3, 1.3, 'AS/400 legacy systems use deeply proprietary protocols; plus integration with payment networks, regulatory reporting systems, branch systems, and other bank infrastructure typical of a core ledger.', '2026-08-05 18:02:12.200894');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('4e3bdca8-8c9f-4f59-b289-389b3f21b517', 'ef06db4b-b9b1-494b-983d-7c32e6c81b52', 'requirement_stability', 'low', -1, 0.9, 'Core ledger migration requirements are largely driven by regulatory and audit constraints; the functional scope is well-defined by the existing AS/400 system, though some clarifications may arise during parallel run.', '2026-08-05 18:02:12.200894');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('10c952ed-d285-4fe6-bf8a-a08360ca8b2a', 'ef06db4b-b9b1-494b-983d-7c32e6c81b52', 'uncertainty', 'high', 1, 1.1, 'AS/400 legacy codebases often contain undocumented business rules, implicit behaviors, and decades of accumulated edge cases that are difficult to fully discover before migration begins.', '2026-08-05 18:02:12.200894');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('08b09dec-04b4-43d8-87b3-37dce328b8e8', 'ef06db4b-b9b1-494b-983d-7c32e6c81b52', 'reliability_requirement', 'very_high', 3, 1.3, 'Bank core ledger handles real financial transactions; errors directly cause financial loss, regulatory violations, and reputational damage — highest reliability class short of life-safety.', '2026-08-05 18:02:12.200894');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('63d7921a-415b-4548-821e-af510d5351fc', 'ef06db4b-b9b1-494b-983d-7c32e6c81b52', 'platform_complexity', 'high', 1, 1.1, 'Modern Java platform must match AS/400 performance characteristics, handle high transaction volumes, and support zero-downtime operations including live reconciliation reporting during parallel run.', '2026-08-05 18:02:12.200894');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('ea7f8f55-c8d4-4b7c-b0b4-ca0c541f1bc9', 'ef06db4b-b9b1-494b-983d-7c32e6c81b52', 'schedule_pressure', 'high', 1, 1.1, 'Bank core system migrations typically have firm regulatory or contractual deadlines; 90-day parallel run window implies a fixed cutover date with significant pressure.', '2026-08-05 18:02:12.200894');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('e86c4981-8b17-4c15-ace5-119ecd1959c3', 'ef06db4b-b9b1-494b-983d-7c32e6c81b52', 'data_complexity', 'very_high', 3, 1.3, 'Decades of financial ledger data must be migrated with full fidelity, reconciliation reporting across both systems for 90 days, complex data transformations from AS/400 schemas, and full audit trail preservation.', '2026-08-05 18:02:12.200894');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('7d0356fb-e47d-4740-840e-ca3e2ebdbcd6', 'ef06db4b-b9b1-494b-983d-7c32e6c81b52', 'team_experience_gap', 'high', 1, 1.1, 'AS/400 RPG/COBOL expertise combined with modern Java platform knowledge and core banking domain experience is a rare combination; most teams will have significant gaps in at least one area.', '2026-08-05 18:02:12.200894');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('9080180d-6295-4be2-bc55-157a4d743db0', '83c4eb4e-af7e-4312-a0a3-d5fd1d9d4573', 'functional_complexity', 'medium', 0, 1, 'Forecast text generation and alert logic involve domain-specific rules, but no research-level algorithms; radar rendering and NWS ingestion are moderately complex.', '2026-08-05 18:02:34.229232');
INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('a68b287b-93c1-452c-9b3d-5825c1345032', '83c4eb4e-af7e-4312-a0a3-d5fd1d9d4573', 'architectural_complexity', 'medium', 0, 1, 'Multiple services (ingestion, rendering, alerting, web portal) with some async processing, but not a full distributed microservices mesh.', '2026-08-05 18:02:34.229232');
