INSERT INTO public.signals (id, "estimationId", "signalName", "rawLevel", ordinal, "adjustmentFactor", "llmRationale", "createdAt") VALUES ('68f6916e-1286-44bf-aca2-7c26f871ff43', '83c4eb4e-af7e-4312-a0a3-d5fd1d9d4573', 'platform_complexity', 'medium', 0, 1, 'Multi-tier cloud deployment with scheduled ingestion jobs, real-time map rendering, and async SMS dispatch; moderate concurrency concerns.', '2026-08-05 18:02:34.229232');
